package com.dating.backend.matching;
import com.dating.backend.entity.*;import com.dating.backend.service.FileStorageService;import com.dating.backend.admin.AdminFilter;import jakarta.persistence.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.mock.web.MockMultipartFile;import java.util.*;import java.io.*;import javax.imageio.ImageIO;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class PhotoDuplicateTest {
 @Autowired EntityManager em;@Autowired PhotoDuplicateService service;@Autowired FileStorageService storage;
 User user(){var u=User.builder().email(UUID.randomUUID()+"@duplicate.test").nickname(UUID.randomUUID().toString()).provider("LOCAL").status("ACTIVE").build();em.persist(u);return u;}
 String photo(User u)throws Exception{var image=new java.awt.image.BufferedImage(64,64,java.awt.image.BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setColor(java.awt.Color.ORANGE);g.fillRect(0,0,64,64);g.dispose();var out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);return storage.storeProfileImage(u.getId(),new MockMultipartFile("file","test.png","image/png",out.toByteArray()));}
 UserProfileImage add(User u,String url){var p=UserProfileImage.builder().userId(u.getId()).imageUrl(url).imageOrder(0).isMain(true).build();em.persist(p);return p;}
 @Test void duplicateReviewAndWithdrawal()throws Exception{var a=user();var b=user();add(a,photo(a));add(b,photo(b));service.scan();var list=service.list(false,0);assertEquals(1,list.size());assertTrue(list.get(0).exact());service.review(list.get(0).id(),true);assertTrue(service.list(false,0).isEmpty());assertEquals(1,service.list(true,0).size());service.review(list.get(0).id(),false);b.setStatus("DELETED");em.flush();assertTrue(service.list(false,0).isEmpty());service.scan();assertEquals(0L,em.createQuery("select count(p) from PhotoDuplicate p",Long.class).getSingleResult());}
 @Test void sameUserDoesNotTriggerAndReplacedPhotoIsRechecked()throws Exception{var a=user();var url=photo(a);add(a,url);var p=add(a,url);service.scan();assertTrue(service.list(false,0).isEmpty());p.setImageUrl(photo(a));service.scan();assertEquals(2L,em.createQuery("select count(f) from PhotoFingerprint f",Long.class).getSingleResult());}
 @Test void boundedBackfill()throws Exception{var a=user();var url=photo(a);for(int i=0;i<12;i++)add(a,url);service.scan();assertEquals(10L,em.createQuery("select count(f) from PhotoFingerprint f",Long.class).getSingleResult());service.scan();assertEquals(12L,em.createQuery("select count(f) from PhotoFingerprint f",Long.class).getSingleResult());}
 @Test void lowInformationImagesAreNotFuzzyMatchesAndPermissions(){assertFalse(PhotoDuplicateService.similar(0,0));long h=0x5555555555555555L;assertTrue(PhotoDuplicateService.similar(h,h^7));assertFalse(PhotoDuplicateService.similar(h,h^15));assertFalse(AdminFilter.allowed("SUPPORT","GET","/api/admin/photo-duplicates"));assertFalse(AdminFilter.allowed("READ_ONLY","PUT","/api/admin/photo-duplicates/1"));assertTrue(AdminFilter.allowed("REVIEWER","PUT","/api/admin/photo-duplicates/1"));}
}
